cat > "$TMPDIR/checkfont.js" <<'EOF'
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  page.on('console', m => console.log('CONSOLE', m.type(), m.text()));
  page.on('requestfailed', r => console.log('REQFAIL', r.url(), r.failure()?.errorText));
  page.on('response', r => { if (r.url().includes('woff')) console.log('RESP', r.status(), r.url(), r.headers()['content-type']); });
  await page.goto('http://127.0.0.1:4173/');
  await page.waitForTimeout(1500);
  const info = await page.evaluate(async () => {
    await document.fonts.ready;
    const faces = [...document.fonts].map(f => ({family:f.family, weight:f.weight, status:f.status}));
    return {
      faces,
      check400: document.fonts.check('400 16px "Acme Sans"'),
      check700: document.fonts.check('700 16px "Acme Sans"'),
      bodyFont: getComputedStyle(document.body).fontFamily,
      h1Font: getComputedStyle(document.querySelector('h1')).fontFamily,
    };
  });
  console.log(JSON.stringify(info, null, 2));
  await browser.close();
})();
EOF
node "$TMPDIR/checkfont.js"

